using System.Text; using CompanyManagement.Api.Data; using CompanyManagement.Api.Repositories; using CompanyManagement.Api.Services; using Microsoft.AspNetCore.Authentication.JwtBearer; using Microsoft.AspNetCore.Identity; using Microsoft.EntityFrameworkCore; using Microsoft.IdentityModel.Tokens; using Microsoft.OpenApi.Models; using StackExchange.Redis;
var builder=WebApplication.CreateBuilder(args); var cs=builder.Configuration.GetConnectionString("DefaultConnection")!; builder.Services.AddDbContext<AppDbContext>(o=>o.UseSqlServer(cs)); builder.Services.AddIdentity<IdentityUser,IdentityRole>(o=>{o.User.RequireUniqueEmail=true;o.Password.RequiredLength=6;o.Password.RequireDigit=true;o.Password.RequireUppercase=true;o.Password.RequireNonAlphanumeric=true;}).AddEntityFrameworkStores<AppDbContext>().AddDefaultTokenProviders(); var jwt=builder.Configuration.GetSection("Jwt");builder.Services.AddAuthentication(o=>{o.DefaultAuthenticateScheme=JwtBearerDefaults.AuthenticationScheme;o.DefaultChallengeScheme=JwtBearerDefaults.AuthenticationScheme;o.DefaultForbidScheme=JwtBearerDefaults.AuthenticationScheme;}).AddJwtBearer(JwtBearerDefaults.AuthenticationScheme,o=>o.TokenValidationParameters=new(){ValidateIssuer=true,ValidIssuer=jwt["Issuer"],ValidateAudience=true,ValidAudience=jwt["Audience"],ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwt["Key"]!)),ValidateLifetime=true,ClockSkew=TimeSpan.Zero}); builder.Services.AddAuthorization(); builder.Services.AddControllers();builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen(o=>o.AddSecurityDefinition("Bearer",new OpenApiSecurityScheme{Type=SecuritySchemeType.Http,Scheme="bearer",BearerFormat="JWT",In=ParameterLocation.Header,Name="Authorization"})); builder.Services.AddSingleton<IConnectionMultiplexer>(_=>ConnectionMultiplexer.Connect(builder.Configuration.GetConnectionString("Redis")!)); builder.Services.AddSingleton<ICacheService,RedisCacheService>();builder.Services.AddScoped<IClienteRepository,ClienteRepository>();builder.Services.AddScoped<IOrdenRepository,OrdenRepository>();builder.Services.AddScoped<IClienteService,ClienteService>();builder.Services.AddScoped<IOrdenService,OrdenService>();builder.Services.AddScoped<IAuthService,AuthService>(); var app=builder.Build();app.UseExceptionHandler(e=>e.Run(async c=>{var f=c.Features.Get<Microsoft.AspNetCore.Diagnostics.IExceptionHandlerFeature>();app.Logger.LogError(f?.Error,"Error no controlado");await Results.Problem(statusCode:500,title:"Error interno del servidor.").ExecuteAsync(c);}));app.UseSwagger();app.UseSwaggerUI();app.UseAuthentication();app.UseAuthorization();app.MapControllers(); using(var scope=app.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<AppDbContext>(); await db.Database.MigrateAsync();var roles=scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();foreach(var r in new[]{"User","Admin"})if(!await roles.RoleExistsAsync(r))await roles.CreateAsync(new IdentityRole(r));var users=scope.ServiceProvider.GetRequiredService<UserManager<IdentityUser>>();var email=app.Configuration["DevelopmentAdmin:Email"]!;if(await users.FindByEmailAsync(email)==null){var u=new IdentityUser{UserName=email,Email=email,EmailConfirmed=true};if((await users.CreateAsync(u,app.Configuration["DevelopmentAdmin:Password"]!)).Succeeded)await users.AddToRoleAsync(u,"Admin");}if(app.Environment.IsDevelopment())await DevelopmentSeeder.Seed(db);} app.Run(); public partial class Program { }
